window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["warp"]={html:"<div class=\"own-warp\">\n  <!-- ── NAV (warm dark, tight radii) ─────────────────────────────────────── -->\n  <header class=\"wp-nav\">\n    <a class=\"wp-logo\" href=\"#wp-top\" aria-label=\"Northwind home\">\n      <span class=\"wp-logo-mark\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"2\"/><path d=\"M7 9l3 3-3 3M13 15h4\"/></svg>\n      </span>\n      <span class=\"wp-wordmark\">Northwind</span>\n    </a>\n    <nav class=\"wp-nav-links\" aria-label=\"Sections\">\n      <a href=\"#wp-product\">Product</a>\n      <a href=\"#wp-customers\">Customers</a>\n      <a href=\"#wp-download\">Download</a>\n      <a href=\"#wp-press\">Press</a>\n    </nav>\n    <div class=\"wp-nav-right\">\n      <a class=\"wp-nav-ghost\" href=\"#wp-download\">Sign in</a>\n      <a class=\"wp-btn wp-btn-primary\" href=\"#wp-download\">Download</a>\n      <button class=\"wp-burger\" type=\"button\" aria-label=\"Menu\" data-wp-burger>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n      </button>\n    </div>\n    <nav class=\"wp-drawer\" aria-label=\"Mobile\" data-wp-drawer hidden>\n      <a href=\"#wp-product\">Product</a>\n      <a href=\"#wp-customers\">Customers</a>\n      <a href=\"#wp-download\">Download</a>\n      <a href=\"#wp-press\">Press</a>\n    </nav>\n  </header>\n\n  <!-- ── HERO (warm dark, split terminal mockups) ─────────────────────────── -->\n  <section class=\"wp-hero\" id=\"wp-top\" aria-labelledby=\"wpHeroH\">\n    <div class=\"wp-shell\">\n      <p class=\"wp-eyebrow\">The agentic operations environment</p>\n      <h1 id=\"wpHeroH\" class=\"wp-display-xl\">Northwind is the operations<br>environment <span class=\"wp-em\">for every region</span>.</h1>\n      <p class=\"wp-lead\">One warm, quiet surface for the dashboards, rollups and agents your teams run all day — with an agent that reads your warehouse so you don&rsquo;t have to.</p>\n      <div class=\"wp-hero-cta\">\n        <a class=\"wp-btn wp-btn-primary\" href=\"#wp-download\">Download for Mac</a>\n        <a class=\"wp-btn wp-btn-ghost\" href=\"#wp-product\">See how it works &rarr;</a>\n      </div>\n\n      <div class=\"wp-terminal-split\">\n        <div class=\"wp-term\" aria-label=\"Agent terminal mockup\">\n          <div class=\"wp-term-head\">\n            <span class=\"wp-term-title\">Northwind Agent</span>\n            <span class=\"wp-term-chip\">Agent</span>\n          </div>\n          <pre class=\"wp-term-body\"><code><span class=\"wp-p\">northwind&gt;</span> <span class=\"wp-cmd\">summarize</span> apac-region --since monday\n<span class=\"wp-dim\">reading 12 dashboards...</span>\n<span class=\"wp-ok\">✓</span> Throughput up <span class=\"wp-num\">4.1×</span> vs last week\n<span class=\"wp-ok\">✓</span> Exceptions flagged: <span class=\"wp-num\">3</span> region(s)\n<span class=\"wp-ok\">✓</span> Draft board pack ready</code></pre>\n        </div>\n        <div class=\"wp-term\" aria-label=\"Terminal session mockup\">\n          <div class=\"wp-term-head\">\n            <span class=\"wp-term-title\">Northwind Terminal</span>\n            <span class=\"wp-term-chip\">Terminal</span>\n          </div>\n          <pre class=\"wp-term-body\"><code><span class=\"wp-p\">~/ops</span> <span class=\"wp-cmd\">nw</span> run nightly-rollup\n<span class=\"wp-dim\">▸ pulling warehouse... done</span>\n<span class=\"wp-dim\">▸ aggregating 48 regions...</span>\n<span class=\"wp-ok\">✓</span> rollup complete in <span class=\"wp-num\">6m 12s</span>\n<span class=\"wp-p\">~/ops</span> <span class=\"wp-cursor\">▍</span></code></pre>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── PARTNER LOGO STRIP ────────────────────────────────────────────────── -->\n  <section class=\"wp-logos\" aria-label=\"Partners\">\n    <div class=\"wp-shell\">\n      <p class=\"wp-eyebrow wp-eyebrow-sm\">Operations teams building on Northwind</p>\n      <div class=\"wp-logo-row\">\n        <span class=\"wp-logo-tile\">Meridian</span>\n        <span class=\"wp-logo-tile\">Northgate</span>\n        <span class=\"wp-logo-tile\">Lattice</span>\n        <span class=\"wp-logo-tile\">Corbin</span>\n        <span class=\"wp-logo-tile\">Halcyon</span>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── FEATURES ──────────────────────────────────────────────────────────── -->\n  <section class=\"wp-band\" id=\"wp-product\" aria-labelledby=\"wpProductH\">\n    <div class=\"wp-shell\">\n      <p class=\"wp-eyebrow\">Built for the desk</p>\n      <h2 id=\"wpProductH\" class=\"wp-display-lg\">Everything the quiet way.</h2>\n      <div class=\"wp-feature-grid\">\n        <article class=\"wp-card\">\n          <span class=\"wp-card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M3 9h18M8 13h8\"/></svg></span>\n          <h3 class=\"wp-display-sm\">Dashboards that behave</h3>\n          <p class=\"wp-body\">Build a board once and it stays legible as data grows — no reflow, no clipping, no last-minute fixes before the review.</p>\n        </article>\n        <article class=\"wp-card\">\n          <span class=\"wp-card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3v5M12 16v5M3 12h5M16 12h5\"/><circle cx=\"12\" cy=\"12\" r=\"4\"/></svg></span>\n          <h3 class=\"wp-display-sm\">An agent that reads</h3>\n          <p class=\"wp-body\">Ask in plain language; the agent queries the warehouse, cites the rows, and drafts the summary you were going to write.</p>\n        </article>\n        <article class=\"wp-card\">\n          <span class=\"wp-card-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16M4 12h16M4 18h10\"/></svg></span>\n          <h3 class=\"wp-display-sm\">Governed by default</h3>\n          <p class=\"wp-body\">Row-level policy and per-team quotas, evaluated at query time, so every region sees exactly its own numbers.</p>\n        </article>\n      </div>\n\n      <!-- terminal mockup feature row -->\n      <div class=\"wp-feature-row\">\n        <div class=\"wp-feature-copy\">\n          <h3 class=\"wp-display-md\">Your workflow, already in the terminal.</h3>\n          <p class=\"wp-body\">Northwind ships as an environment, not a portal. Pipe rollups, schedule agents, and keep your shell prompt exactly where it belongs.</p>\n          <ul class=\"wp-check-list\">\n            <li>Native Mac, Linux and Windows builds</li>\n            <li>Offline-first — sync when the region reconnects</li>\n            <li>Bring your own model provider</li>\n          </ul>\n        </div>\n        <div class=\"wp-term wp-term-lg\" aria-label=\"Workflow mockup\">\n          <div class=\"wp-term-head\"><span class=\"wp-term-title\">ops.config</span></div>\n          <pre class=\"wp-term-body\"><code><span class=\"wp-key\">region</span>   = <span class=\"wp-str\">\"apac\"</span>\n<span class=\"wp-key\">schedule</span> = <span class=\"wp-str\">\"0 6 * * *\"</span>\n<span class=\"wp-key\">agent</span>    = <span class=\"wp-str\">\"regional-rollup\"</span>\n\n<span class=\"wp-com\"># every board, refreshed before the standup</span></code></pre>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── TESTIMONIAL ───────────────────────────────────────────────────────── -->\n  <section class=\"wp-band wp-band-tight\" id=\"wp-customers\" aria-labelledby=\"wpQuoteH\">\n    <div class=\"wp-shell\">\n      <h2 id=\"wpQuoteH\" class=\"wp-display-lg wp-sr-only\">What operators say</h2>\n      <figure class=\"wp-quote\">\n        <div class=\"wp-portrait\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 96 96\"><rect width=\"96\" height=\"96\" fill=\"#413a35\"/><circle cx=\"48\" cy=\"38\" r=\"18\" fill=\"#c9c0ad\"/><path d=\"M18 96c4-20 16-30 30-30s26 10 30 30z\" fill=\"#c9c0ad\"/></svg>\n        </div>\n        <blockquote class=\"wp-quote-text\">The warmth is not cosmetic. Northwind is the first operations tool my team opens on purpose — and the first one the regional managers actually keep open.</blockquote>\n        <figcaption>\n          <span class=\"wp-quote-name\">Priya Raghunathan</span>\n          <span class=\"wp-quote-role\">VP OPERATIONS &middot; NORTHGATE FREIGHT</span>\n        </figcaption>\n      </figure>\n    </div>\n  </section>\n\n  <!-- ── PRESS ──────────────────────────────────────────────────────────────── -->\n  <section class=\"wp-band wp-band-tight\" id=\"wp-press\" aria-labelledby=\"wpPressH\">\n    <div class=\"wp-shell\">\n      <p class=\"wp-eyebrow\">In the news</p>\n      <h2 id=\"wpPressH\" class=\"wp-display-md\">Press coverage</h2>\n      <ul class=\"wp-press\">\n        <li class=\"wp-press-row\"><span class=\"wp-press-source\">The Operator</span><span class=\"wp-press-title\">Northwind wants to make operations dashboards quiet again</span><span class=\"wp-press-date\">Mar 2026</span></li>\n        <li class=\"wp-press-row\"><span class=\"wp-press-source\">Terminal Weekly</span><span class=\"wp-press-title\">Why an agentic environment beats another web portal</span><span class=\"wp-press-date\">Feb 2026</span></li>\n        <li class=\"wp-press-row\"><span class=\"wp-press-source\">Scale Review</span><span class=\"wp-press-title\">The warm-dark canvas, and other lessons in restraint</span><span class=\"wp-press-date\">Jan 2026</span></li>\n      </ul>\n    </div>\n  </section>\n\n  <!-- ── DOWNLOAD ──────────────────────────────────────────────────────────── -->\n  <section class=\"wp-band\" id=\"wp-download\" aria-labelledby=\"wpDownloadH\">\n    <div class=\"wp-shell\">\n      <p class=\"wp-eyebrow\">Get started</p>\n      <h2 id=\"wpDownloadH\" class=\"wp-display-lg\">Download Northwind.</h2>\n      <div class=\"wp-download-grid\">\n        <a class=\"wp-dl-tile\" href=\"#wp-top\">\n          <span class=\"wp-dl-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M16 4c-3 0-5 2-5 5.5C13.5 9.5 15.5 8 16 4z\"/><path d=\"M16 4c-4.5.5-8 3.5-8 8 0 3.5 2 6 5 6 1.5 0 2-.6 3-.6s1.5.6 3 .6c3 0 5-2.5 5-6 0-4.5-3.5-7.5-8-8z\"/></svg></span>\n          <span class=\"wp-dl-name\">macOS</span>\n          <span class=\"wp-dl-meta\">Apple silicon &amp; Intel &middot; 48 MB</span>\n        </a>\n        <a class=\"wp-dl-tile\" href=\"#wp-top\">\n          <span class=\"wp-dl-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3c2 3 3 7 3 11 0 4-1.5 6-3 7-1.5-1-3-3-3-7 0-4 1-8 3-11z\"/><path d=\"M12 12c3 1 5 3 6 6-3 .5-5-.5-6-2\"/><path d=\"M12 12c-3 1-5 3-6 6 3 .5 5-.5 6-2\"/></svg></span>\n          <span class=\"wp-dl-name\">Linux</span>\n          <span class=\"wp-dl-meta\">.deb &amp; .rpm &middot; 42 MB</span>\n        </a>\n        <a class=\"wp-dl-tile\" href=\"#wp-top\">\n          <span class=\"wp-dl-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 4h8v8H3zM13 4h8v8h-8zM3 14h8v6H3zM13 14h8v6h-8z\"/></svg></span>\n          <span class=\"wp-dl-name\">Windows</span>\n          <span class=\"wp-dl-meta\">x64 &amp; ARM64 &middot; 51 MB</span>\n        </a>\n        <a class=\"wp-dl-tile wp-dl-ghost\" href=\"#wp-product\">\n          <span class=\"wp-dl-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16M4 12h16M4 18h10\"/></svg></span>\n          <span class=\"wp-dl-name\">Command line</span>\n          <span class=\"wp-dl-meta\">brew install northwind</span>\n        </a>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── FOOTER ─────────────────────────────────────────────────────────────── -->\n  <footer class=\"wp-foot\">\n    <div class=\"wp-shell\">\n      <div class=\"wp-foot-top\">\n        <div class=\"wp-foot-brand\">\n          <span class=\"wp-wordmark\">Northwind</span>\n          <p class=\"wp-foot-tag\">The operations environment for every region.</p>\n        </div>\n        <nav class=\"wp-foot-links\" aria-label=\"Footer\">\n          <a href=\"#wp-product\">Product</a>\n          <a href=\"#wp-customers\">Customers</a>\n          <a href=\"#wp-press\">Press</a>\n          <a href=\"#wp-download\">Download</a>\n          <a href=\"#\">Privacy</a>\n          <a href=\"#\">Terms</a>\n        </nav>\n      </div>\n      <p class=\"wp-foot-note\">Sample data &mdash; showcase only. Northwind is a fictional product.</p>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ WARP — warm-dark terminal language, ported for showcase.html ══════════\n   Scoped under `.own-warp`. One warm near-charcoal canvas (#2b2622), an\n   off-white \"primary\", tight 3–4px radii, Inter + DM Mono, Instrument Serif\n   italic moments. Production breakpoints become @container frame queries. */\n\n.own-warp {\n  --primary: #f7f5f0;\n  --on-primary: #2b2622;\n  --ink: #f7f5f0;\n  --body: #c9c0ad;\n  --body-strong: #dad2c1;\n  --mute: #aea69c;\n  --canvas: #2b2622;\n  --canvas-soft: #383330;\n  --hairline: #3f3a36;\n\n  --sans: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;\n  --mono: 'DM Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;\n  --serif: 'Instrument Serif', Georgia, 'Times New Roman', serif;\n  --gut: clamp(18px, 3cqi, 40px);\n  --shell: 1200px;\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--sans);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  overflow-x: clip;\n}\n\n.own-warp *, .own-warp *::before, .own-warp *::after { box-sizing: border-box; }\n.own-warp a { color: inherit; }\n.own-warp :focus-visible { outline: 3px solid var(--primary); outline-offset: 3px; border-radius: 4px; }\n.own-warp .wp-shell { width: 100%; max-width: var(--shell); margin: 0 auto; padding: 0 var(--gut); }\n.own-warp .wp-sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n.own-warp .wp-em { font-family: var(--serif); font-style: italic; font-weight: 400; letter-spacing: -0.5px; }\n\n/* ── type ─────────────────────────────────────────────────────────────────── */\n.own-warp .wp-display-xl {\n  margin: 0; font-weight: 400; font-size: clamp(36px, 5.4cqi, 64px);\n  line-height: 1.08; letter-spacing: -1.6px; color: var(--ink);\n}\n.own-warp .wp-display-lg {\n  margin: 0; font-weight: 400; font-size: clamp(28px, 3.6cqi, 48px);\n  line-height: 1.1; letter-spacing: -1.2px; color: var(--ink);\n}\n.own-warp .wp-display-md { margin: 0; font-weight: 500; font-size: clamp(22px, 2.6cqi, 32px); line-height: 1.25; letter-spacing: -0.8px; }\n.own-warp .wp-display-sm { margin: 0; font-weight: 500; font-size: 24px; line-height: 1.3; letter-spacing: -0.4px; }\n.own-warp .wp-eyebrow { margin: 0 0 16px; font-weight: 500; font-size: 14px; line-height: 20px; text-transform: uppercase; letter-spacing: .08em; color: var(--mute); }\n.own-warp .wp-eyebrow-sm { font-size: 12px; }\n.own-warp .wp-lead { margin: 22px 0 0; font-size: clamp(17px, 1.5cqi, 18px); line-height: 28px; color: var(--body); max-width: 58ch; }\n.own-warp .wp-body { margin: 12px 0 0; font-size: 16px; line-height: 24px; color: var(--body); }\n\n/* ── buttons (tight 3px radii) ───────────────────────────────────────────── */\n.own-warp .wp-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  font-family: var(--sans); font-size: 14px; font-weight: 500; line-height: 20px;\n  padding: 8px 16px; border-radius: 3px; border: 1px solid transparent;\n  text-decoration: none; cursor: pointer; white-space: nowrap;\n  transition: background-color .18s ease, border-color .18s ease, color .18s ease;\n}\n.own-warp .wp-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-warp .wp-btn-primary:hover { background: #ffffff; }\n.own-warp .wp-btn-ghost { background: transparent; color: var(--ink); border-color: var(--hairline); }\n.own-warp .wp-btn-ghost:hover { border-color: var(--body-strong); }\n\n/* ── nav ──────────────────────────────────────────────────────────────────── */\n.own-warp .wp-nav {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 24px;\n  padding: 10px var(--gut);\n  background: rgba(43, 38, 34, .94);\n  border-bottom: 1px solid var(--hairline);\n  backdrop-filter: blur(8px);\n}\n.own-warp .wp-logo { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; }\n.own-warp .wp-wordmark { font-weight: 500; font-size: 18px; letter-spacing: -0.3px; color: var(--ink); }\n.own-warp .wp-logo-mark { display: grid; place-items: center; width: 28px; height: 28px; border-radius: 4px; background: var(--canvas-soft); border: 1px solid var(--hairline); color: var(--ink); }\n.own-warp .wp-logo-mark svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n.own-warp .wp-nav-links { display: flex; align-items: center; gap: 6px; }\n.own-warp .wp-nav-links a { padding: 6px 10px; border-radius: 3px; color: var(--ink); font-size: 14px; font-weight: 500; text-decoration: none; }\n.own-warp .wp-nav-links a:hover { background: var(--canvas-soft); }\n.own-warp .wp-nav-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }\n.own-warp .wp-nav-ghost { color: var(--ink); font-size: 14px; font-weight: 500; text-decoration: none; }\n.own-warp .wp-nav-ghost:hover { color: var(--body-strong); }\n.own-warp .wp-burger { display: none; place-items: center; width: 40px; height: 40px; border: 1px solid var(--hairline); border-radius: 4px; background: transparent; color: var(--ink); cursor: pointer; }\n.own-warp .wp-burger svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }\n.own-warp .wp-drawer { display: none; }\n.own-warp .wp-drawer:not([hidden]) { display: flex; flex-direction: column; gap: 2px; flex-basis: 100%; margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--hairline); }\n.own-warp .wp-drawer a { color: var(--ink); text-decoration: none; padding: 10px 4px; font-size: 15px; border-radius: 3px; }\n.own-warp .wp-drawer a:hover { background: var(--canvas-soft); }\n\n/* ── hero ─────────────────────────────────────────────────────────────────── */\n.own-warp .wp-hero { padding: clamp(56px, 8cqi, 112px) 0 clamp(40px, 5cqi, 72px); }\n.own-warp .wp-hero-cta { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 28px; }\n.own-warp .wp-terminal-split { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; margin-top: clamp(36px, 5cqi, 64px); }\n\n/* ── terminal cards ───────────────────────────────────────────────────────── */\n.own-warp .wp-term { background: var(--canvas-soft); border: 1px solid var(--hairline); border-radius: 4px; overflow: hidden; }\n.own-warp .wp-term-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 14px; border-bottom: 1px solid var(--hairline); }\n.own-warp .wp-term-title { font-family: var(--mono); font-size: 12px; color: var(--mute); }\n.own-warp .wp-term-chip { font-size: 11px; font-weight: 500; letter-spacing: .06em; text-transform: uppercase; color: var(--body-strong); padding: 2px 8px; border-radius: 9999px; border: 1px solid var(--hairline); }\n.own-warp .wp-term-body { margin: 0; padding: 18px; overflow-x: auto; font-family: var(--mono); font-size: 13px; line-height: 20px; color: var(--body-strong); }\n.own-warp .wp-term-body code { font-family: inherit; }\n.own-warp .wp-p { color: var(--primary); }\n.own-warp .wp-cmd { color: var(--body-strong); }\n.own-warp .wp-dim { color: var(--mute); }\n.own-warp .wp-ok { color: #8fd4a8; }\n.own-warp .wp-num { color: #e0b98a; }\n.own-warp .wp-key { color: var(--primary); }\n.own-warp .wp-str { color: #d8b98e; }\n.own-warp .wp-com { color: var(--mute); }\n.own-warp .wp-cursor { color: var(--body-strong); animation: wp-blink 1.1s steps(1) infinite; }\n@keyframes wp-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }\n\n/* ── logo strip ───────────────────────────────────────────────────────────── */\n.own-warp .wp-logos { padding: 8px 0 clamp(28px, 3cqi, 40px); }\n.own-warp .wp-logo-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 16px; }\n.own-warp .wp-logo-tile {\n  flex: 1 1 140px; display: grid; place-items: center; padding: 16px;\n  background: var(--canvas-soft); border: 1px solid var(--hairline); border-radius: 4px;\n  font-weight: 500; font-size: 15px; color: var(--body-strong); opacity: .9;\n}\n\n/* ── bands ────────────────────────────────────────────────────────────────── */\n.own-warp .wp-band { padding: clamp(52px, 6cqi, 96px) 0; }\n.own-warp .wp-band-tight { padding-top: clamp(24px, 3cqi, 40px); padding-bottom: clamp(24px, 3cqi, 40px); }\n\n.own-warp .wp-feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-top: 40px; }\n.own-warp .wp-card { background: var(--canvas-soft); border: 1px solid var(--hairline); border-radius: 4px; padding: 24px; }\n.own-warp .wp-card-icon { display: grid; place-items: center; width: 40px; height: 40px; margin-bottom: 18px; border-radius: 4px; background: var(--canvas); border: 1px solid var(--hairline); color: var(--ink); }\n.own-warp .wp-card-icon svg { width: 22px; height: 22px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n\n.own-warp .wp-feature-row { display: grid; grid-template-columns: 1fr 1.1fr; gap: clamp(24px, 4cqi, 48px); align-items: center; margin-top: clamp(40px, 5cqi, 72px); }\n.own-warp .wp-check-list { list-style: none; margin: 20px 0 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.own-warp .wp-check-list li { position: relative; padding-left: 24px; font-size: 15px; line-height: 22px; color: var(--body-strong); }\n.own-warp .wp-check-list li::before { content: ''; position: absolute; left: 0; top: .42em; width: 10px; height: 6px; border-left: 2px solid var(--primary); border-bottom: 2px solid var(--primary); transform: rotate(-45deg); }\n.own-warp .wp-term-lg { aspect-ratio: 3 / 2; display: flex; flex-direction: column; }\n.own-warp .wp-term-lg .wp-term-body { flex: 1; }\n\n/* ── testimonial ──────────────────────────────────────────────────────────── */\n.own-warp .wp-quote {\n  display: grid; grid-template-columns: 96px 1fr; gap: 24px; align-items: center;\n  margin: 0; padding: 32px;\n  background: var(--canvas-soft); border: 1px solid var(--hairline); border-radius: 4px;\n}\n.own-warp .wp-portrait { width: 96px; height: 96px; border-radius: 4px; overflow: hidden; }\n.own-warp .wp-portrait svg { width: 100%; height: 100%; display: block; }\n.own-warp .wp-quote-text { margin: 0; grid-column: 2; font-family: var(--serif); font-style: italic; font-size: clamp(22px, 2.6cqi, 30px); line-height: 1.35; letter-spacing: -0.4px; color: var(--ink); }\n.own-warp .wp-quote figcaption { grid-column: 2; display: flex; flex-direction: column; gap: 2px; margin-top: 14px; }\n.own-warp .wp-quote-name { font-weight: 500; font-size: 15px; color: var(--ink); }\n.own-warp .wp-quote-role { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: var(--mute); font-family: var(--mono); }\n\n/* ── press ─────────────────────────────────────────────────────────────────── */\n.own-warp .wp-press { list-style: none; margin: 20px 0 0; padding: 0; }\n.own-warp .wp-press-row { display: grid; grid-template-columns: 160px 1fr auto; gap: 20px; align-items: baseline; padding: 16px 0; border-bottom: 1px solid var(--hairline); }\n.own-warp .wp-press-row:first-child { border-top: 1px solid var(--hairline); }\n.own-warp .wp-press-source { font-family: var(--mono); font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--mute); }\n.own-warp .wp-press-title { font-size: 16px; font-weight: 500; color: var(--ink); }\n.own-warp .wp-press-date { font-size: 13px; color: var(--mute); }\n\n/* ── download ─────────────────────────────────────────────────────────────── */\n.own-warp .wp-download-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-top: 36px; }\n.own-warp .wp-dl-tile {\n  display: flex; flex-direction: column; gap: 6px;\n  padding: 24px; border-radius: 4px; text-decoration: none;\n  background: var(--canvas-soft); border: 1px solid var(--hairline);\n  transition: border-color .18s ease, background-color .18s ease;\n}\n.own-warp .wp-dl-tile:hover { border-color: var(--body-strong); background: #3d3833; }\n.own-warp .wp-dl-ghost { background: transparent; }\n.own-warp .wp-dl-icon { display: grid; place-items: center; width: 34px; height: 34px; margin-bottom: 8px; color: var(--ink); }\n.own-warp .wp-dl-icon svg { width: 28px; height: 28px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }\n.own-warp .wp-dl-name { font-weight: 500; font-size: 16px; color: var(--ink); }\n.own-warp .wp-dl-meta { font-size: 13px; color: var(--mute); }\n\n/* ── footer ───────────────────────────────────────────────────────────────── */\n.own-warp .wp-foot { border-top: 1px solid var(--hairline); padding: 48px 0 40px; }\n.own-warp .wp-foot-top { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 24px; }\n.own-warp .wp-foot-brand { display: flex; flex-direction: column; gap: 6px; }\n.own-warp .wp-foot-tag { margin: 0; font-size: 14px; color: var(--body); }\n.own-warp .wp-foot-links { display: flex; flex-wrap: wrap; gap: 20px; }\n.own-warp .wp-foot-links a { color: var(--body); font-size: 14px; text-decoration: none; }\n.own-warp .wp-foot-links a:hover { color: var(--ink); }\n.own-warp .wp-foot-note { margin: 32px 0 0; padding-top: 24px; border-top: 1px solid var(--hairline); font-size: 12px; color: var(--mute); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-warp .wp-feature-grid { grid-template-columns: 1fr; }\n  .own-warp .wp-download-grid { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 900px) {\n  .own-warp .wp-nav-links { display: none; }\n  .own-warp .wp-feature-row { grid-template-columns: 1fr; }\n  .own-warp .wp-press-row { grid-template-columns: 1fr auto; }\n  .own-warp .wp-press-source { grid-column: 1 / -1; }\n}\n@container frame (max-width: 760px) {\n  .own-warp .wp-nav { top: 10px; flex-wrap: wrap; gap: 12px; }\n  .own-warp .wp-burger { display: grid; }\n  .own-warp .wp-terminal-split { grid-template-columns: 1fr; }\n  .own-warp .wp-quote { grid-template-columns: 1fr; text-align: left; }\n  .own-warp .wp-quote-text, .own-warp .wp-quote figcaption { grid-column: 1; }\n  .own-warp .wp-quote-text { margin-top: 8px; }\n}\n@container frame (max-width: 520px) {\n  .own-warp .wp-download-grid { grid-template-columns: 1fr; }\n  .own-warp .wp-nav-ghost { display: none; }\n}\n@container frame (max-width: 430px) {\n  .own-warp .wp-hero-cta { width: 100%; }\n  .own-warp .wp-hero-cta .wp-btn { flex: 1 1 100%; }\n  .own-warp .wp-term-body { font-size: 12px; }\n  .own-warp .wp-dl-tile { padding: 18px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-warp *, .own-warp *::before, .own-warp *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n  .own-warp .wp-cursor { animation: none; }\n}\n"};
/* ══ WARP — behaviour for showcase.html ════════════════════════════════════
   Registers window.OWN_LAYOUTS['warp'].init(root). Wires the mobile drawer and
   in-layout anchor scrolling. init returns a cleanup that aborts every
   listener it registered. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['warp'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $(sel) { return root.querySelector(sel); }

      var burger = $('[data-wp-burger]');
      var drawer = $('[data-wp-drawer]');
      on(burger, 'click', function () {
        if (!drawer) return;
        var open = drawer.hasAttribute('hidden');
        if (open) drawer.removeAttribute('hidden'); else drawer.setAttribute('hidden', '');
        burger.setAttribute('aria-expanded', String(open));
      });

      Array.prototype.forEach.call(root.querySelectorAll('a[href^="#"]'), function (a) {
        on(a, 'click', function (e) {
          var href = a.getAttribute('href');
          if (!href || href.length < 2) return;
          var target = root.querySelector(href);
          if (!target) return;
          e.preventDefault();
          target.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
          if (drawer && !drawer.hasAttribute('hidden')) {
            drawer.setAttribute('hidden', '');
            if (burger) burger.setAttribute('aria-expanded', 'false');
          }
          try { history.replaceState(null, '', href); } catch (err) { /* ignore */ }
        });
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
